package dev.mineagent.runtime.neoforge.client.webui;
import dev.mineagent.runtime.neoforge.ui.FullImportSmokeServer;import dev.mineagent.runtime.neoforge.network.PanelSnapshotInbox;import dev.mineagent.runtime.neoforge.client.screen.ControlCenterScreen;import net.minecraft.client.Minecraft;import java.nio.file.*;import java.util.*;
public final class FullImportSmokeClient {
 private static int ticks,wait;private static boolean done;
 public static void tick()throws Exception{if(done)return;var mc=Minecraft.getInstance();ticks++;Path root=Files.createDirectories(mc.gameDirectory.toPath().resolve("full-import-smoke"));try{if(!FullImportSmokeServer.failure.isEmpty())throw new IllegalStateException(FullImportSmokeServer.failure);if(ticks>3000)throw new IllegalStateException("FULL_IMPORT_TIMEOUT");if(mc.player==null||!FullImportSmokeServer.ready)return;if(!FullImportSmokeServer.clientReady){String fp=PanelSnapshotInbox.snapshot().values().getOrDefault("security.identityFingerprint","");if(fp.isEmpty()||new dev.mineagent.runtime.client.trust.ServerTrustStore(mc.gameDirectory.toPath().resolve("config/mineagent-trusted-servers.properties")).status("local-integrated",fp)!=dev.mineagent.runtime.client.trust.TrustStatus.TRUSTED){if(mc.screen instanceof ControlCenterScreen s)for(var c:List.copyOf(s.children()))if(c instanceof net.minecraft.client.gui.components.Button b&&b.active&&b.getMessage().getString().contains("信任此服务器"))b.onPress(new net.minecraft.client.input.KeyEvent(257,0,0));return;}if(++wait==1)mc.player.connection.sendCommand("ai accept");if(wait<40)return;FullImportSmokeServer.clientReady=true;mc.setScreen(null);}if(FullImportSmokeServer.complete){done=true;Files.writeString(root.resolve("client.json"),"{\"status\":\"FULL_CONTENTS_ZERO_MODEL_CLIENT_COMPLETE\"}");dev.mineagent.runtime.neoforge.MineAgentRuntimeMod.LOGGER.info("MINEAGENT_CONVERSATION_AGENT_OK");mc.stop();}}catch(Exception e){done=true;Files.writeString(root.resolve("failure.txt"),e.toString());mc.stop();}}
 private FullImportSmokeClient(){}
}
